head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.screenId = "jlddst50100";
scwin.isExaService = null;
scwin.svrGubun = null;
scwin.listStatCd = null;

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function () {
    try {
        scwin.init_recvParam();
        scwin.isExaService = String((((cv) => (cv !== undefined && cv !== null && cv !== "") ? cv : (typeof scwin.isExaService !== "undefined" && scwin.isExaService !== null ? scwin.isExaService : (console.warn("[sdd] 컨텍스트 키 미충전 — " + "isExaService" + " (as-is EL 부재 = 빈값이라 진행합니다)"), "")))(dma_pageContext.get("isExaService"))) == null ? '' : (((cv) => (cv !== undefined && cv !== null && cv !== "") ? cv : (typeof scwin.isExaService !== "undefined" && scwin.isExaService !== null ? scwin.isExaService : (console.warn("[sdd] 컨텍스트 키 미충전 — " + "isExaService" + " (as-is EL 부재 = 빈값이라 진행합니다)"), "")))(dma_pageContext.get("isExaService")))).indexOf('$' + '{') >= 0 ? '' : String((((cv) => (cv !== undefined && cv !== null && cv !== "") ? cv : (typeof scwin.isExaService !== "undefined" && scwin.isExaService !== null ? scwin.isExaService : (console.warn("[sdd] 컨텍스트 키 미충전 — " + "isExaService" + " (as-is EL 부재 = 빈값이라 진행합니다)"), "")))(dma_pageContext.get("isExaService"))) == null ? '' : (((cv) => (cv !== undefined && cv !== null && cv !== "") ? cv : (typeof scwin.isExaService !== "undefined" && scwin.isExaService !== null ? scwin.isExaService : (console.warn("[sdd] 컨텍스트 키 미충전 — " + "isExaService" + " (as-is EL 부재 = 빈값이라 진행합니다)"), "")))(dma_pageContext.get("isExaService"))));
        scwin.svrGubun = "" + dma_pageContext.get("svrGubun") + "";
        scwin.listStatCd = String((((cv) => (cv !== undefined && cv !== null && cv !== "") ? cv : (typeof scwin.listStatCd !== "undefined" && scwin.listStatCd !== null ? scwin.listStatCd : (console.warn("[sdd] 컨텍스트 키 미충전 — " + "listStatCd" + " (as-is EL 부재 = 빈값이라 진행합니다)"), "")))(dma_pageContext.get("listStatCd"))) == null ? '' : (((cv) => (cv !== undefined && cv !== null && cv !== "") ? cv : (typeof scwin.listStatCd !== "undefined" && scwin.listStatCd !== null ? scwin.listStatCd : (console.warn("[sdd] 컨텍스트 키 미충전 — " + "listStatCd" + " (as-is EL 부재 = 빈값이라 진행합니다)"), "")))(dma_pageContext.get("listStatCd")))).indexOf('$' + '{') >= 0 ? '' : String((((cv) => (cv !== undefined && cv !== null && cv !== "") ? cv : (typeof scwin.listStatCd !== "undefined" && scwin.listStatCd !== null ? scwin.listStatCd : (console.warn("[sdd] 컨텍스트 키 미충전 — " + "listStatCd" + " (as-is EL 부재 = 빈값이라 진행합니다)"), "")))(dma_pageContext.get("listStatCd"))) == null ? '' : (((cv) => (cv !== undefined && cv !== null && cv !== "") ? cv : (typeof scwin.listStatCd !== "undefined" && scwin.listStatCd !== null ? scwin.listStatCd : (console.warn("[sdd] 컨텍스트 키 미충전 — " + "listStatCd" + " (as-is EL 부재 = 빈값이라 진행합니다)"), "")))(dma_pageContext.get("listStatCd"))));
        await scwin.init_rowCopy();
        await scwin.init_pageBody();
    } catch (e) {
        await $c.exception.handleError(e, { context: 'jlddst50100.onpageload' });
    }
};

/**
 * @method
 * @name init_rowCopy
 * @description dataList 단건 표시 복사 — 진입점에서 1회. 데이터 재적재 시 ev:ondataload 가 다시 부른다.
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.init_rowCopy = async function () {
    const rows = [{ childId: "ipt_listStatCd", fn: function () { return String(String(((cv) => (cv !== undefined && cv !== null && cv !== "") ? cv : (typeof scwin.listStatCd !== "undefined" && scwin.listStatCd !== null ? scwin.listStatCd : ""))(dma_pageContext.get("listStatCd")))); } },
        { childId: "ipt_listStatCd2", fn: function () { return String(String(((cv) => (cv !== undefined && cv !== null && cv !== "") ? cv : (typeof scwin.listStatCd !== "undefined" && scwin.listStatCd !== null ? scwin.listStatCd : ""))(dma_pageContext.get("listStatCd")))); } }];
    let copied = 0;
    for (let i = 0; i < rows.length; i++) {
        const it = rows[i];
        const c = $c.util.getComponent(it.childId);
        if (!c || typeof c.setValue !== "function") { /* TODO Stage2: [sdd] 행 복사 대상 부재:  it.childId */ continue; }
        try {
            const v = it.fn();
            if (v !== undefined && v !== null && String(v).trim() !== "") { c.setValue(String(v)); copied++; }
        } catch (e) { await $c.exception.handleError(e, { notify: "none", context: "rowCopy:" + it.childId }); }
    }
    return copied;
};

/**
 * @method
 * @name init_pageBody
 * @description 초기화 — page Body
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.init_pageBody = async function () {
    try {
        $("#searchForm").find("#formUpClassCd").val("00");
        await scwin.fnCorpInfoSearch();
        await scwin.fnMainDisclosureSearch();
        if (scwin.isExaService === "Y" && scwin.svrGubun.indexOf("dr") < 0 && scwin.listStatCd === "Y") {
            await scwin.fnPrincipalIndexSearch();
        }

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jlddst50100.onpageload' }); }
};

/**
 * @method
 * @name init_recvParam
 * @description 화면 전환 파라미터 수신 — $c.data.getParameter() 를 dma_pageContext 에 담는다
 * @returns {void}
 * @hidden N
 */
scwin.init_recvParam = function () { dma_pageContext.setJSON($c.data.getParameter() ?? {}); };

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name btn_fnOnClickTab_onclick
 * @description 「전체(${cnt.cnt00})」 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_fnOnClickTab_onclick = async function(e){
    try {
        await scwin.fnOnClickTab('00'); return false;

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jlddst50100.btn_fnOnClickTab_onclick' }); }
};

