///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name fnCorpInfoSearch
 * @description fn Corp Info Search 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.fnCorpInfoSearch = async function () {
    await scwin.tx_fnCorpInfoSearch_ajaxsubmit();
};

/**
 * @method
 * @name fnPrincipalIndexSearch
 * @description fn Principal Index Search 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.fnPrincipalIndexSearch = async function () {
    await scwin.tx_fnPrincipalIndexSearch_ajaxsubmit();
};

/**
 * @method
 * @name fnOnClickTab
 * @description fn On Click Tab 처리
 * @param {*} type type
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.fnOnClickTab = async function (type) {
    $(".tabgroup").find("a").each(function(i) {
            $(this).removeClass("active");
    });
    if (type === "-1") {
        $(".tab-99").addClass("active");
    } else {
        $(".tab-" + type).addClass("active");
    }
    $("#searchForm").find("#formUpClassCd").val(type);
    $c.util.getComponent("dma_fnCorpInfoSearchAjaxsubmitReq").set("pageIndex", "1");
    await scwin.fnMainDisclosureSearch();
};

/**
 * @method
 * @name fnSearch1
 * @description fn Search1 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.fnSearch1 = async function () {
    $c.util.getComponent("dma_fnCorpInfoSearchAjaxsubmitReq").set("pageIndex", "1");
    $c.util.getComponent("dma_fnCorpInfoSearchAjaxsubmitReq").set("currentPageSize", $(document).find("select[id=ipt_currentPageSize]").val());
    await scwin.fnMainDisclosureSearch();
};

/**
 * @method
 * @name fnMainDisclosureSearch
 * @description fn Main Disclosure Search 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.fnMainDisclosureSearch = async function () {
    await scwin.tx_fnMainDisclosureSearch_ajaxsubmit();
};

/**
 * @method
 * @name fnMainDisclosureSearchCallBack
 * @description fn Main Disclosure Search Call Back 처리
 * @param {*} data 데이터
 * @returns {void}
 * @hidden N
 */
scwin.fnMainDisclosureSearchCallBack = function (data) {
    $(".contents-list").empty().append(data);
    $("tr:odd").addClass("active");
    /* TODO Stage2: [sdd] 미실현(재설계 분류 #128): fnLegendTooltip( " ') */
};
